// Find the sung melody ("right hand") track in a MIDI file.
//
// 1. If the file has lyric events and one track's notes start where the
//    lyric syllables do (at least 60% of them), that's the melody. Certain.
// 2. Otherwise a small neural net scores every non-drum track and a softmax
//    over the tracks gives a probability. The features are: note count,
//    monophony, pitch (mean, spread, rank), coverage, note length, interval
//    sizes, how often the track is the top voice ("skyline"), track name
//    hints, channel and instrument family. It was trained on the 8,134 songs
//    in the Lyrics MIDI Dataset whose lyrics pinpoint the melody track, and
//    gets 85% right on held-out songs (92% of the ones it's >=70% sure about).
//    Training: tools/extract_melody_features.mjs + tools/train_melody.py.

const VOCAL_NAME = /vocal|voice|vox|\bvoz\b|sing|melod|lyric|chant|canto|stimme|\bvoix\b|\bmelodie\b/i;
const NEG_NAME = /bass|drum|perc|kick|snare|hi-?hat|cymbal|\btoms?\b|pad|chord|rhythm|comp\b|accomp|backing|harmony|arp|left\s*hand|strings/i;

const FAMILY = (p) => Math.floor(p / 8); // 16 GM families

// Per-track feature vectors (non-drum tracks with at least 8 notes).
export function trackFeatures(song) {
  const cands = song.tracks.map((t, i) => ({ t, i })).filter(({ t }) => !t.isDrums && t.notes.length >= 8);
  const stats = cands.map(({ t, i }) => {
    const notes = t.notes;
    const n = notes.length;
    let wsum = 0, psum = 0, p2 = 0, overlaps = 0, maxEnd = -Infinity, covered = 0, curS = -1, curE = -1;
    let steps = 0, small = 0, repeats = 0, absInt = 0, durSum = 0;
    let prev = null;
    for (const x of notes) {
      const end = x.time + x.duration;
      psum += x.midi * x.duration; p2 += x.midi * x.midi * x.duration; wsum += x.duration; durSum += x.duration;
      if (maxEnd > x.time + 0.03) overlaps++;
      maxEnd = Math.max(maxEnd, end);
      if (x.time > curE) { if (curE > curS) covered += curE - curS; curS = x.time; curE = end; } else curE = Math.max(curE, end);
      if (prev && x.time - prev.time > 0.03) {
        const d = Math.abs(x.midi - prev.midi);
        steps++; absInt += d; if (d <= 2) small++; if (d === 0) repeats++;
      }
      prev = x;
    }
    if (curE > curS) covered += curE - curS;
    const pitch = wsum ? psum / wsum : 60;
    return {
      t, i, n, pitch,
      pstd: wsum ? Math.sqrt(Math.max(0, p2 / wsum - pitch * pitch)) : 0,
      mono: n ? 1 - overlaps / n : 0,
      coverage: song.duration ? Math.min(1, covered / song.duration) : 0,
      meanDur: durSum / n,
      interval: steps ? absInt / steps : 0,
      small: steps ? small / steps : 0,
      repeats: steps ? repeats / steps : 0,
    };
  });
  // skyline share: how often each track has the highest sounding note (50 ms grid)
  const STEP = 0.05, G = Math.ceil(song.duration / STEP) + 1;
  const top = new Float32Array(G).fill(-1), owner = new Int16Array(G).fill(-1);
  stats.forEach((st, k) => {
    for (const x of st.t.notes) {
      const g0 = Math.ceil(x.time / STEP), g1 = Math.min(G - 1, Math.floor((x.time + x.duration) / STEP));
      for (let g = g0; g <= g1; g++) if (x.midi > top[g]) { top[g] = x.midi; owner[g] = k; }
    }
  });
  const sky = new Array(stats.length).fill(0);
  let sounding = 0;
  for (let g = 0; g < G; g++) if (owner[g] >= 0) { sky[owner[g]]++; sounding++; }
  const maxN = Math.max(1, ...stats.map((s) => s.n));
  const byPitch = [...stats].sort((a, b) => b.pitch - a.pitch);
  return stats.map((s, k) => {
    const rank = byPitch.indexOf(s);
    const skyShare = sounding ? sky[k] / sounding : 0;
    const activeSky = s.coverage > 0 ? skyShare / Math.max(0.05, s.coverage) : 0;
    const fam = new Array(16).fill(0); fam[FAMILY(s.t.program)] = 1;
    const x = [
      1,
      Math.log(s.n) / 5,
      s.mono,
      (s.pitch - 64) / 12, ((s.pitch - 64) / 12) ** 2,
      s.pstd / 12,
      stats.length > 1 ? rank / (stats.length - 1) : 0,
      rank === 0 ? 1 : 0,
      s.n / maxN,
      s.coverage, s.coverage ** 2,
      Math.log(s.meanDur + 0.01),
      s.interval / 12, s.small, s.repeats,
      VOCAL_NAME.test(s.t.name) ? 1 : 0,
      NEG_NAME.test(s.t.name) ? 1 : 0,
      /right\s*hand/i.test(s.t.name) ? 1 : 0,
      (s.t.program >= 52 && s.t.program <= 54) || s.t.program === 85 ? 1 : 0,
      s.t.channel === 0 ? 1 : 0,
      skyShare, Math.min(2, activeSky),
      ...fam,
    ];
    return { index: s.i, x, mono: s.mono };
  });
}

// Fraction of lyric events that line up with a note onset in each track.
export function lyricMatches(song) {
  const lyricTimes = (song.lyrics || []).map((l) => l.time);
  if (lyricTimes.length < 16) return song.tracks.map(() => 0);
  return song.tracks.map((t) => {
    const onsets = t.notes.map((x) => x.time);
    if (!onsets.length) return 0;
    let hit = 0;
    for (const lt of lyricTimes) {
      let lo = 0, hi = onsets.length - 1;
      while (lo < hi) { const mid = (lo + hi) >> 1; if (onsets[mid] < lt - 0.08) lo = mid + 1; else hi = mid; }
      if (Math.abs(onsets[lo] - lt) <= 0.08) hit++;
    }
    return hit / lyricTimes.length;
  });
}

