const B1 = [0.3047, 0.0112, 0.0284, -0.003, 0.0746, -0.2121, -0.042, 0.0068, 0.2626, 0.0053, -0.3454, -0.3452, 0.0406, 0.2087, -0.1532, 0.1475, 0.0796, -0.1352, 0.3415, -0.192, 0.2212, -0.3447, 0.2614, 0.2671];
const W2 = [-0.5362, -0.0964, -1.2781, 1.0845, -1.8176, 1.2274, 0.7664, -0.0975, -0.7627, -0.064, 0.5568, 1.2355, -0.6766, 1.1805, 0.3249, -0.7209, -0.3397, 0.9098, -1.2872, 0.7945, -1.1817, 1.1535, -0.8937, -0.9222];

function mlpScore(x) {
  let out = 0;
  for (let h = 0; h < B1.length; h++) {
    let a = B1[h];
    for (let d = 0; d < x.length; d++) a += x[d] * W1[d][h];
    out += Math.tanh(a) * W2[h];
  }
  return out;
}

/**
 * @returns { index, confidence (0..1), source: 'lyrics'|'model'|'only', polyphonic }
 * polyphonic = the melody track also plays chords (e.g. a solo piano part),
 * so the sung line should be its top notes.
 */
export function guessMelody(song) {
  const feats = trackFeatures(song);
  if (!feats.length) return { index: -1, confidence: 0, source: 'none', polyphonic: false };
  const lm = lyricMatches(song);
  let li = -1, lv = 0.6;
  for (const f of feats) if (lm[f.index] > lv) { lv = lm[f.index]; li = f.index; }
  const monoOf = (i) => feats.find((f) => f.index === i).mono;
  if (li >= 0) return { index: li, confidence: 1, source: 'lyrics', polyphonic: monoOf(li) < 0.6 };
  if (feats.length === 1) {
    const f = feats[0];
    return { index: f.index, confidence: f.mono >= 0.75 ? 0.75 : 0.5, source: 'only', polyphonic: f.mono < 0.6 };
  }
  const z = feats.map((f) => mlpScore(f.x));
  const mx = Math.max(...z);
  const e = z.map((v) => Math.exp(v - mx));
  const sum = e.reduce((a, b) => a + b, 0);
  let bi = 0;
  for (let k = 1; k < z.length; k++) if (z[k] > z[bi]) bi = k;
  return { index: feats[bi].index, confidence: e[bi] / sum, source: 'model', polyphonic: feats[bi].mono < 0.6 };
}
